var NEXT = {
  'Submitted': ['Evaluated'],
  'Evaluated': ['Approved', 'Rejected'],
  'Approved': ['Change Made'],
  'Change Made': ['Verified'],
  'Verified': ['Closed'],
  'Rejected': [], 'Closed': [], 'Canceled': [],
};
var FINAL = ['Rejected', 'Closed', 'Canceled'];

function canMove(from, to) {
  if (!NEXT.hasOwnProperty(from) || !NEXT.hasOwnProperty(to)) return false;
  if (to === 'Canceled') return FINAL.indexOf(from) < 0;
  return NEXT[from].indexOf(to) >= 0;
}
